// Comment text and usernames are written by strangers. The message is sent in Telegram's HTML
// mode, so escape & < > to show them as plain text (Markdown would break on a username like a_b).
const escape = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

const comments = $input.all().map((item) => item.json).filter((c) => c.id);
if (comments.length === 0) return [];

const lines = comments.map((c) => {
  const who = c.author_username ? '@' + c.author_username : 'Someone';
  const account = c.account?.username ? '@' + c.account.username : (c.account?.display_name ?? '');
  const text = (c.text ?? '').replace(/\s+/g, ' ').trim().slice(0, 160) || '(no text)';
  return `- <b>${escape(who)}</b> on ${escape(c.account?.platform)} ${escape(account)}: ${escape(text)}`;
});

// Telegram allows 4096 characters per message: add whole lines only, so no tag is cut in half.
const header = `<b>${comments.length} comment(s) waiting for a reply</b>\n`;
const footer = '\nReply in Tebar: https://publish.tebar.app/comments';
let body = '';
let shown = 0;
for (const line of lines) {
  if (header.length + body.length + line.length + footer.length + 40 > 4096) break;
  body += '\n' + line;
  shown++;
}
if (shown < lines.length) body += `\n...and ${lines.length - shown} more`;

return [{ json: { message: header + body + '\n' + footer } }];
